sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float radius;
uniform float magnification;
uniform float distortion;
uniform float softEdge;
uniform float border;
layout(color) uniform half4 borderColor;
uniform float shadow;
uniform float shape;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float dist = shape < 0.5 ? length(d) : max(abs(d.x), abs(d.y));
    float inside = 1.0 - smoothstep(radius * (1.0 - softEdge), radius, dist);
    float q = saturate(dist / radius);
    float mag = mix(magnification, 1.0, pow(q, 1.0 + distortion * 3.0));
    float4 lens = tex(ctr + d / mag);
    float ring = smoothstep(radius - border - 1.0, radius - border, dist) * (1.0 - smoothstep(radius - 1.0, radius, dist));
    lens = float4(mix(lens.rgb, float3(borderColor.rgb) * lens.a, ring), lens.a);
    float sh = (1.0 - smoothstep(radius, radius * 1.25 + 1.0, dist)) * (1.0 - inside) * shadow;
    float4 base = float4(c.rgb * (1.0 - sh), c.a);
    return fin(c, mix(base, lens, inside), opacity);
}
